"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/ecommerce/variants/02-product-detail";
export interface ArtemisEcommerceProductDetailProps { className?: string;  }
export function ArtemisEcommerceProductDetail({ className }: ArtemisEcommerceProductDetailProps) {return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View0/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { useId as useArtemisInstanceId } from "react";
import { Listbox, ListboxButton, ListboxOption, ListboxOptions } from "../../../lib/headless";
import { motion, useReducedMotion } from "motion/react";
import { useRef, useState } from "react";
import { ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { bundles, images, type BundleValue } from "./02-product-detail/images";
const navClass = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border-border art:text-foreground art:hover:border-border art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:border-0 art:bg-background art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full";
const thumbClass = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:shrink-0 art:overflow-hidden art:p-0 art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9";
function Chevron({ direction }: {
    direction: "left" | "right";
}) {
    return <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-chevron-${direction} art:size-4`} aria-hidden="true"><path d={direction === "left" ? "m15 18-6-6 6-6" : "m9 18 6-6-6-6"}/></svg>;
}
function Check({ className }: {
    className: string;
}) {
    return <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-check ${className}`} aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>;
}
function ShoppingBag() {
    return <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-shopping-bag art:size-4" aria-hidden="true"><path d="M16 10a4 4 0 0 1-8 0"/><path d="M3.103 6.034h17.794"/><path d="M3.4 5.467a2 2 0 0 0-.4 1.2V20a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6.667a2 2 0 0 0-.4-1.2l-2-2.667A2 2 0 0 0 17 2H7a2 2 0 0 0-1.6.8z"/></svg>;
}
export default function EcommerceProductDetail() {
const artemisInstanceId = useArtemisInstanceId();


    const reducedMotion = useReducedMotion();
    const [active, setActive] = useState(0);
    const [bundle, setBundle] = useState<BundleValue>("standard");
    const [message, setMessage] = useState("");
    const carouselRef = useRef<HTMLDivElement>(null);
    const selectedBundle = bundles.find(item => item.value === bundle) ?? bundles[0];
    const goTo = (index: number) => {
        const next = Math.max(0, Math.min(images.length - 1, index));
        const node = carouselRef.current;
        if (node)
            node.scrollTo({ left: next * node.clientWidth, behavior: reducedMotion ? "auto" : "smooth" });
    };
    const onScroll = () => {
        const node = carouselRef.current;
        if (node && node.clientWidth)
            setActive(Math.max(0, Math.min(images.length - 1, Math.round(node.scrollLeft / node.clientWidth))));
    };
    return <section className="art:w-full art:bg-background art:px-4 art:py-16 art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-20">
    <div className="art:mx-auto art:grid art:max-w-6xl art:items-center art:gap-8 art:@min-[1024px]/artemis:grid-cols-2 art:@min-[1024px]/artemis:gap-16">
      <div className="art:min-w-0">
        <div className="art:relative art:overflow-hidden art:rounded-3xl art:bg-muted">
          <div ref={carouselRef} role="group" aria-roledescription="carousel" aria-label="Studio headphones images" tabIndex={0} className="art:scrollbar-hide art:flex art:snap-x art:snap-mandatory art:overflow-x-auto art:overscroll-x-contain art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-inset art:focus-visible:ring-ring" onScroll={onScroll} onKeyDown={event => {
            if (event.key === "ArrowRight") {
                event.preventDefault();
                goTo(active + 1);
            }
            if (event.key === "ArrowLeft") {
                event.preventDefault();
                goTo(active - 1);
            }
            if (event.key === "Home") {
                event.preventDefault();
                goTo(0);
            }
            if (event.key === "End") {
                event.preventDefault();
                goTo(images.length - 1);
            }
        }}>
            {images.map((image, index) => <div key={image.alt} role="group" aria-roledescription="slide" aria-label={`${index + 1} of ${images.length}`} aria-hidden={active !== index} className="art:aspect-square art:w-full art:shrink-0 art:snap-center art:snap-always"><img src={image.src} alt={image.alt} width="1000" height="1000" loading={index === 0 ? "eager" : "lazy"} draggable="false" className="art:size-full art:object-cover"/></div>)}
          </div>
          <span className="art:pointer-events-none art:absolute art:left-5 art:top-5 art:rounded-full art:bg-background/95 art:px-3 art:py-1.5 art:text-xs art:font-medium">Bestseller</span>
          <div className="art:absolute art:bottom-4 art:right-4 art:flex art:items-center art:gap-2">
            <motion.button type="button" className={navClass} disabled={active === 0} aria-label="Previous product image" tabIndex={0} whileHover={reducedMotion ? undefined : { scale: 1.01 }} whileTap={reducedMotion ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => goTo(active - 1)}><Chevron direction="left"/></motion.button>
            <motion.button type="button" className={navClass} disabled={active === images.length - 1} aria-label="Next product image" tabIndex={0} whileHover={reducedMotion ? undefined : { scale: 1.01 }} whileTap={reducedMotion ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => goTo(active + 1)}><Chevron direction="right"/></motion.button>
          </div>
        </div>
        <div className="art:mt-4 art:flex art:items-center art:justify-between art:gap-4">
          <div className="art:flex art:min-w-0 art:gap-2 art:overflow-x-auto art:p-1">{images.map((image, index) => <motion.button key={image.alt} type="button" className={`${thumbClass} ${active === index ? "art:ring-2 art:ring-foreground art:ring-offset-2 art:ring-offset-background" : "art:opacity-60 art:hover:opacity-100"} art:rounded-full`} aria-label={`Show product image ${index + 1}: ${image.alt}`} aria-pressed={active === index} tabIndex={0} whileHover={reducedMotion ? undefined : { scale: 1.01 }} whileTap={reducedMotion ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => goTo(index)}><img src={image.src} alt="" width="56" height="56" loading="lazy" className="art:size-full art:object-cover"/></motion.button>)}</div>
          <output className="art:shrink-0 art:text-xs art:tabular-nums art:text-muted-foreground"><span className="art:sr-only">Image </span>{active + 1}{" / "}{images.length}</output>
        </div>
      </div>
      <div className="art:max-w-lg">
        <p className="art:text-sm art:text-muted-foreground">{"Audio"}{" / The everyday collection"}</p>
        <h2 className="art:mt-4 art:tracking-tight art:text-xl art:font-medium">Studio headphones</h2>
        <p className="art:mt-4 art:text-sm art:leading-7 art:text-muted-foreground art:@min-[640px]/artemis:text-base">A little more focus. A lot more of your favorite music.</p>
        <p className="art:mt-5 art:text-xl art:font-medium art:tabular-nums">{`$${selectedBundle.price.toFixed(2)}`}</p>
        <ul className="art:mt-7 art:space-y-3">
          {["Comfortable over-ear fit", "Wireless listening, wired when you need it", "A simple design made for daily use"].map(feature => <li key={feature} className="art:flex art:items-start art:gap-3 art:text-sm"><span className="art:flex art:size-5 art:shrink-0 art:items-center art:justify-center art:rounded-full art:bg-muted"><Check className="art:size-3"/></span>{feature}</li>)}
        </ul>
        <div className="art:mt-8">
          <p className="art:mb-2 art:text-sm art:font-medium">Choose your set</p>
          <Listbox as="div" value={bundle} onChange={setBundle} className="art:relative art:inline-block art:text-left art:w-full">
            <ListboxButton id={`headlessui-listbox-button-${artemisInstanceId}-R_3ed9bsnpfdb_`} aria-label="Product bundle" className="art:inline-flex art:min-w-40 art:items-center art:gap-2 art:border art:border-border art:text-left art:font-medium art:text-foreground art:text-sm art:transition-colors art:hover:border-border-strong art:disabled:pointer-events-none art:disabled:opacity-50 art:outline-none art:ring-0 art:focus:outline-none art:focus:ring-0 art:focus-visible:outline-none art:data-focus:outline-none art:data-focus:ring-0 art:data-open:ring-0 art:h-10 art:w-full art:justify-between art:rounded-full art:bg-background art:px-4 art:focus-visible:ring-2 art:focus-visible:ring-ring">{({ open }) => <><span className="art:min-w-0 art:truncate">{selectedBundle.label}</span><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-chevron-down art:size-4 art:shrink-0 art:text-muted-foreground art:transition-transform${open ? " art:rotate-180" : ""}`} aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></>}</ListboxButton>
            <ListboxOptions id={`headlessui-listbox-options-${artemisInstanceId}-R_5ed9bsnpfdb_`} anchor={{ to: "bottom start", gap: 8, padding: 12 }} transition className="art:z-[120] art:overflow-hidden art:rounded-2xl art:border art:border-border-strong/50 art:bg-background art:p-1.5 art:backdrop-blur-xl art:outline-none art:ring-0 art:focus:outline-none art:focus:ring-0 art:focus-visible:outline-none art:focus-visible:ring-0 art:data-focus:outline-none art:data-focus:ring-0 art:transition art:duration-150 art:ease-out art:data-closed:scale-95 art:data-closed:opacity-0 art:origin-top art:w-[var(--button-width)] art:shadow-none art:max-w-[calc(100vw-1.5rem)]">
              {bundles.map(item => <ListboxOption key={item.value} value={item.value} className="art:group art:flex art:min-h-11 art:cursor-pointer art:items-center art:gap-3 art:rounded-xl art:px-3 art:py-2 art:text-left art:transition-colors art:data-focus:bg-primary/5 art:data-disabled:pointer-events-none art:data-disabled:opacity-50"><span className="art:min-w-0 art:flex-1"><span className="art:block art:truncate art:text-sm">{item.label}</span><span className="art:block art:truncate art:text-muted-foreground art:text-xs">{item.description}</span></span><Check className="art:size-4 art:shrink-0 art:opacity-0 art:group-data-selected:opacity-100"/></ListboxOption>)}
            </ListboxOptions>
          </Listbox>
          <p className="art:mt-2 art:min-h-5 art:text-xs art:text-muted-foreground">{selectedBundle.description}</p>
        </div>
        <motion.button type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-6 art:w-full art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full" tabIndex={0} whileHover={reducedMotion ? undefined : { scale: 1.01 }} whileTap={reducedMotion ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => setMessage(`Studio headphones \u00B7 ${selectedBundle.label} added to the demo bag.`)}><ShoppingBag />Add to bag</motion.button>
        <p className="art:mt-4 art:flex art:items-center art:gap-2 art:text-xs art:text-muted-foreground"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-truck art:size-4" aria-hidden="true"><path d="M14 18V6a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v11a1 1 0 0 0 1 1h2"/><path d="M15 18H9"/><path d="M19 18h2a1 1 0 0 0 1-1v-3.65a1 1 0 0 0-.22-.624l-3.48-4.35A1 1 0 0 0 17.52 8H14"/><circle cx="17" cy="18" r="2"/><circle cx="7" cy="18" r="2"/></svg>Shipping calculated at checkout</p>
        <output className="art:mt-4 art:block art:min-h-10 art:text-sm art:text-muted-foreground">{message}</output>
      </div>
    </div>
  </section>;
}

// @zeus-internal
export const images = [
    { src: "/assets/artemis/4c17834a46e15e761658.avif", alt: "Studio headphones, full product view" },
    { src: "/assets/artemis/ed9b404e28ed900e2031.avif", alt: "Studio headphones, cropped detail view" },
    { src: "/assets/artemis/a24c15ec88743794a96b.avif", alt: "Studio headphones, second close-up" },
] as const;
export const bundles = [
    { value: "standard", label: "Standard", description: "Headphones and charging cable", price: 129 },
    { value: "travel", label: "Travel set", description: "Add a protective case and cable pouch", price: 154 },
] as const;
export type BundleValue = (typeof bundles)[number]["value"];
